contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function driving C and asserting a general invariant
    // Parameters:
    //  - account: the account on whose behalf openMakeFor is invoked
    //  - amount: the UFixed18 amount to open (treated as uint256 since UFixed18 is a typedef)
    function run(address account, uint256 amount) public payable {
        // No precondition on c's state (fresh c). Bound amount to avoid absurd values.
        require(amount <= type(uint128).max, "amount bounds");

        // Observe pre-state: the account's pre().openPosition.maker and latestVersion(account)
        C.PrePosition memory preBefore = c.pre(account);
        uint256 beforeOpenMaker = preBefore.openPosition.maker; // UFixed18 is uint256 alias
        uint256 beforeLatestVersionAccount = c.latestVersion(account);

        // Attempt the mutable call and capture whether it reverted
        bool reverted;
        try c.openMakeFor(account, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe post-state
        C.PrePosition memory preAfter = c.pre(account);
        uint256 afterOpenMaker = preAfter.openPosition.maker;
        uint256 afterLatestVersionAccount = c.latestVersion(account);

        // General rule asserted:
        // If the call did not revert, then the account's pending open maker (pre.openPosition.maker)
        // must have increased by at least `amount` (i.e., after >= before + amount), and the latestVersion(account)
        // must be unchanged by openMakeFor (settleForAccount should have been executed before mutation)
        assert(
            reverted || (afterOpenMaker >= beforeOpenMaker + amount && afterLatestVersionAccount == beforeLatestVersionAccount)
        );
    }

    receive() external payable {}
}

