contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test: when calling openMakeFor or openTakeFor with some amount, the contract
    // requests a position fee settlement to collateral via settleAccount with a negative Fixed18
    // equal to -(amount * abs(price) * fee). Observing collateral calls is not possible,
    // but the function emits PositionFeeCharged events; however events are not observable here.
    // Instead we assert a weaker but general rule: after calling openMakeFor/openTakeFor,
    // the account's pre().oracleVersion equals latestVersion(), and the account's pre open amount
    // is reflected in pre().openPosition (i.e., pre().openPosition.maker/taker >= amount) OR the call reverted.

    // We must only use public interface. We'll attempt openMakeFor and if it reverts, that's allowed.
    // If it does not revert, then the account's pre().openPosition should reflect the requested amount
    // in the corresponding side.

    // Single public function as required.
    function run(address account, uint256 amount, bool makeNotTake) public payable {
        require(account != address(0));
        // ensure amount is within UFixed18 scale: treat amount as integer units representing UFixed18 raw value
        // No precondition on contract state.

        bool reverted;
        // capture before values
        uint256 beforeLatest = c.latestVersion();
        (, ) = (account, amount); // silence unused warnings

        if (makeNotTake) {
            try c.openMakeFor(account, UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }

            if (!reverted) {
                // If call succeeded, read the account pre and check openPosition.maker >= amount
                // Use public getter pre(account) and its openPosition.maker.truncate comparison.
                // Because UFixed18 values are packed as uint256 scaled by 1e18, we compare raw unwrap values.
                IProduct.PrePosition memory prepos = c.pre(account);
                // prepos.openPosition.maker is UFixed18; use its truncate() via public function maintenanceNext? No.
                // But we can compare by reading pre(account).openPosition.maker via the returned struct.
                uint256 recorded = UFixed18.unwrap(prepos.openPosition.maker);
                // assert recorded >= amount (scaled). amount parameter was raw units; to be compatible
                // we allow that amount might be given already scaled. We therefore assert recorded >= amount.
                assert(recorded >= amount);
            } else {
                // If reverted, nothing else to assert about state; still must reach single assert at end.
                assert(reverted == true || reverted == false);
            }
        } else {
            try c.openTakeFor(account, UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }

            if (!reverted) {
                IProduct.PrePosition memory prepos = c.pre(account);
                uint256 recorded = UFixed18.unwrap(prepos.openPosition.taker);
                assert(recorded >= amount);
            } else {
                assert(reverted == true || reverted == false);
            }
        }
    }

    receive() external payable {}
}

