contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test that successful openMakeFor/openTakeFor records at least the requested open amount
    // in the account's pre().openPosition for the appropriate side.
    function run(address account, uint256 rawAmount, bool doMake) public payable {
        require(account != address(0));

        // Wrap the rawAmount into UFixed18 by calling the public factory on C via its public view functions is not available,
        // but UFixed18 is a typedef in the compilation unit; however we cannot construct UFixed18 directly in solidity code
        // since it's an alias. The contract C expects UFixed18 as parameter type; passing uint256 will compile because
        // the underlying type is uint256. So we pass rawAmount directly.

        bool reverted;
        if (doMake) {
            try c.openMakeFor(account, UFixed18.wrap(rawAmount)) {
                reverted = false;
            } catch {
                reverted = true;
            }

            // Read the pre-position via the public getter pre(address)
            (uint256 settleVersion, (uint256 maker, uint256 taker) memory openPosition, (uint256 cmaker, uint256 ctaker) memory closePosition) = abi.decode(abi.encodePacked(c.pre(account)), (uint256, uint256, uint256, uint256, uint256, uint256));
            // The above decode is not reliable; instead call the public getter and read component values via the returned tuple types.
        } else {
            try c.openTakeFor(account, UFixed18.wrap(rawAmount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Now obtain the PrePosition using the public pre(address) function and assert the invariant.
        // Due to solidity tuple return unpacking, we directly call and destructure.
        (uint256 oracleVersion, 
         UFixed18 openMaker, UFixed18 openTaker,
         UFixed18 closeMaker, UFixed18 closeTaker) = _getPrePosition(account);

        // Convert the recorded UFixed18 wrapped values to raw uint256 via the public truncate-like access: UFixed18.unwrap is not callable here,
        // but since UFixed18 is an underlying uint256 type, assigning to uint256 works.
        uint256 recordedMaker = uint256(openMaker);
        uint256 recordedTaker = uint256(openTaker);

        // Assert: if call did not revert then the corresponding recorded open side is >= rawAmount
        assert(reverted || (doMake ? recordedMaker >= rawAmount : recordedTaker >= rawAmount));
    }

    // Helper to call the public pre(address) getter and return components in a stable way.
    // The getter signature in C is: function pre(address account) external view returns (PrePosition memory)
    // PrePosition has fields: uint256 oracleVersion; Position openPosition; Position closePosition;
    // Position has UFixed18 maker; UFixed18 taker;
    function _getPrePosition(address account) internal view returns (
        uint256,
        UFixed18, UFixed18,
        UFixed18, UFixed18
    ) {
        // We rely on Solidity's ability to tuple-decode the returned struct via an external call.
        // Since we cannot name the struct type here, we perform a low-level call to fetch the abi-encoded return
        // and decode it with the expected types.
        bytes memory ret = address(c).staticcall(abi.encodeWithSignature("pre(address)", account)) ? abi.encodePacked() : abi.encodePacked();
        (uint256 oracleVersion, uint256 openMakerRaw, uint256 openTakerRaw, uint256 closeMakerRaw, uint256 closeTakerRaw) = abi.decode(ret, (uint256, uint256, uint256, uint256, uint256));
        return (oracleVersion, UFixed18.wrap(openMakerRaw), UFixed18.wrap(openTakerRaw), UFixed18.wrap(closeMakerRaw), UFixed18.wrap(closeTakerRaw));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // If openMakeFor/openTakeFor returns (doesn't revert), then the account's pre().openPosition
    // records at least the requested amount on the corresponding side.
    // We take `account`, `rawAmount`, and `doMake` as inputs. UFixed18 is represented by uint256
    // (its underlying type), so we pass the rawAmount directly.
    function run(address account, uint256 rawAmount, bool doMake) public payable {
        require(account != address(0));

        bool reverted;
        if (doMake) {
            try c.openMakeFor(account, rawAmount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.openTakeFor(account, rawAmount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Read the PrePosition via the public getter pre(address)
        // The ABI encoding of PrePosition is: (uint256 oracleVersion, (uint256 maker,uint256 taker) openPosition, (uint256 maker,uint256 taker) closePosition)
        // So the returned tuple decodes as (uint256, uint256, uint256, uint256, uint256)
        (bool ok, bytes memory ret) = address(c).staticcall(abi.encodeWithSignature("pre(address)", account));
        // staticcall should succeed (view) - if it fails treat as empty return so assertion still meaningful
        uint256 oracleVersion;
        uint256 openMakerRaw;
        uint256 openTakerRaw;
        uint256 closeMakerRaw;
        uint256 closeTakerRaw;
        if (ok && ret.length >= 32 * 5) {
            (oracleVersion, openMakerRaw, openTakerRaw, closeMakerRaw, closeTakerRaw) = abi.decode(ret, (uint256, uint256, uint256, uint256, uint256));
        } else {
            // If decode failed, set recorded opens to 0 so the property still holds only when reverted==true
            oracleVersion = 0;
            openMakerRaw = 0;
            openTakerRaw = 0;
            closeMakerRaw = 0;
            closeTakerRaw = 0;
        }

        // Assert the general rule: if the respective call did NOT revert then the recorded open side >= rawAmount
        assert(reverted || (doMake ? (openMakerRaw >= rawAmount) : (openTakerRaw >= rawAmount)));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We accept the raw underlying uint256 representation of UFixed18 as the amount.
    // If the call returns (no revert), then the corresponding pre(account).openPosition side
    // must be at least the amount passed.
    function run(address account, uint256 amountRaw, bool doMake) public payable {
        require(account != address(0));

        bool reverted;
        // Build the UFixed18 typed value by ABI-encoding and decoding to match the expected type
        // when calling the contract. We perform the call via try/catch on the external function.
        if (doMake) {
            try c.openMakeFor{value: 0}(account, UFixed18(amountRaw)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.openTakeFor{value: 0}(account, UFixed18(amountRaw)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Now read pre(account) via the public getter. The ABI for pre(address) returns
        // (uint256 oracleVersion, (uint256 maker,uint256 taker) openPosition, (uint256 maker,uint256 taker) closePosition)
        // which flattens to five uint256 values.
        (bool ok, bytes memory ret) = address(c).staticcall(abi.encodeWithSignature("pre(address)", account));

        uint256 oracleVersion = 0;
        uint256 openMakerRaw = 0;
        uint256 openTakerRaw = 0;
        uint256 closeMakerRaw = 0;
        uint256 closeTakerRaw = 0;
        if (ok && ret.length >= 32 * 5) {
            (oracleVersion, openMakerRaw, openTakerRaw, closeMakerRaw, closeTakerRaw) = abi.decode(ret, (uint256, uint256, uint256, uint256, uint256));
        }

        // Assert: if the call did not revert then the recorded open side >= amountRaw.
        assert(reverted || (doMake ? (openMakerRaw >= amountRaw) : (openTakerRaw >= amountRaw)));
    }

    // Solidity doesn't allow constructing user-defined value types directly in external call sites in older solc versions.
    // To make UFixed18(...) compile, we provide a fallback that allows the test contract to be compiled
    // by defining a minimal conversion function through internal assembly-style encoding — but since we cannot
    // add functions, we instead declare a user-defined value type alias here to satisfy the type name used above.
    // However, adding such a declaration is not allowed per instructions. To work around, declare an empty receive.
    receive() external payable {}
}

