contract InvMutTest {
    C c;
    IController controller;

    constructor(C _c) {
        c = _c;
        controller = c.controller();
    }

    // We will call openMakeFor or openTakeFor depending on `isMake`.
    // Inputs:
    // - account: target account to open for (must be != address(this) to exercise onlyAccountOrMultiInvoker path differently)
    // - amount: UFixed18 encoded as uint256 (value in base units, but we just pass through)
    // - isMake: whether to call openMakeFor (true) or openTakeFor (false)
    // The function is payable to satisfy any position fee side-effects, but we won't send Ether to c in this test.
    function run(address account, uint256 amount, bool isMake) public payable {
        require(account != address(0), "zero account");
        // Read some before-values: collateral fees for account (via controller.collateral().fees)
        ICollateral col = controller.collateral();
        // Must not call any state-changing c function inside expressions; these are view calls.
        UFixed18 beforeFees = col.fees(address(this));

        // Determine price/versions via public view to compute expected sign of position fee effect
        // We cannot access internal payoff math, but we can call c.atVersion and c.latestVersion() to obtain price
        uint256 latestV = c.latestVersion();
        IOracleProvider.OracleVersion memory latestOracle = c.atVersion(latestV);
        // Compute magnitude of position fee in the same fashion as C: amount * price.abs() * feeRate
        // We can read makerFee/takerFee and price.abs() via public getters
        UFixed18 amt = UFixed18.wrap(amount);
        UFixed18 feeRate = isMake ? c.makerFee() : c.takerFee();
        Fixed18 price = latestOracle.price;
        UFixed18 positionFeeMagnitude = amt.mul(price.abs()).mul(feeRate);

        // Now perform the action and capture whether it reverted.
        bool reverted;
        if (isMake) {
            try c.openMakeFor(account, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.openTakeFor(account, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Read collateral fees after the call
        UFixed18 afterFees = col.fees(address(this));

        // The general rule we assert:
        // - positionFeeMagnitude is always non-negative (by construction of UFixed18),
        // - if positionFeeMagnitude is zero then the collateral.fees for this contract shouldn't decrease (no negative settlement happened), i.e., afterFees >= beforeFees
        // We express this as: positionFeeMagnitude == 0 implies afterFees.gte(beforeFees)
        // Use public UFixed18.gte via library as a call in the assert expression.
        assert((positionFeeMagnitude.eq(UFixed18Lib.ZERO) ? afterFees.gte(beforeFees) : true));
    }

    receive() external payable {}
}

