    // single entry: take account address and two UFixed18 amounts encoded as uint256
    function run(address account, uint256 openAmountRaw, uint256 closeAmountRaw) public payable {
        require(account != address(0));
        // Interpret raw inputs as UFixed18 by wrapping via the public constructor functions are not available here,
        // but public functions accept UFixed18 (a typedef to uint256), so pass raw uint256 values directly.

        // Read pre-state: maker position for account
        C.Position memory beforePos = c.position(account);
        uint256 beforeMaker = beforePos.maker.unwrap();

        // call openMakeFor: this may revert; capture revert flag
        bool openReverted;
        try c.openMakeFor(account, UFixed18.wrap(openAmountRaw)) {
            openReverted = false;
        } catch {
            openReverted = true;
        }

        // call closeMakeFor: authorized only if msg.sender is owner() or account; our contract is not owner so may revert
        bool closeReverted;
        try c.closeMakeFor(account, UFixed18.wrap(closeAmountRaw)) {
            closeReverted = false;
        } catch {
            closeReverted = true;
        }

        // After operations, read resulting position
        C.Position memory afterPos = c.position(account);
        uint256 afterMaker = afterPos.maker.unwrap();

        // General rule: closing should not increase maker exposure beyond what was before minus closed amount.
        // If closeMakeFor succeeded (closeReverted == false) then afterMaker <= beforeMaker + (openSucceeded ? openAmountRaw : 0) - closeAmountRaw
        // To avoid needing openSucceeded separately, compute allowed upper bound conservatively:
        // The maker position cannot exceed beforeMaker + openAmountRaw (if open succeeded); if open reverted then no increase expected.
        // So assert: afterMaker <= beforeMaker + (openReverted ? 0 : openAmountRaw)
        // And if close succeeded, also afterMaker + closeAmountRaw >= beforeMaker (i.e., closing actually reduced or at most emptied to no less than before minus closed)

        // Compose the property as single boolean expression
        bool prop;
        uint256 maxAllowed = beforeMaker + (openReverted ? 0 : openAmountRaw);
        if (!closeReverted) {
            // close succeeded: ensure it didn't increase beyond what open could have added, and that close reduced appropriately
            prop = (afterMaker <= maxAllowed) && (afterMaker + closeAmountRaw >= beforeMaker);
        } else {
            // close reverted: still ensure that maker didn't unexpectedly grow beyond what open could have added
            prop = (afterMaker <= maxAllowed);
        }

        assert(prop);
    }

    receive() external payable {}
}

