contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single-entry test. We try to open either maker or taker; if the call succeeds
    // then the account's pre() next open amount for that side must have increased by exactly the input amount,
    // and the function must not have reverted. We also check that when the call reverts, the pre() was unchanged.
    // Parameters:
    // - account: the target account for openMakeFor / openTakeFor
    // - amount: the UFixed18 amount to open
    // - isMake: if true call openMakeFor, otherwise call openTakeFor
    // The test uses only public/external observations: c.pre(account) and revert flag.

    function run(address account, UFixed18 amount, bool isMake) public payable {
        require(account != address(0) ? true : true);

        // observe pre-position before
        (uint256 beforeVersion, , ) = c.pre(account);
        // We cannot destructure PrePosition easily; use the public getter c.pre(account) returns (PrePosition memory)
        // but Solidity does not let us access internals; instead, call c.pre(account) and then read via position/close?
        // The PrePosition type has fields oracleVersion, openPosition, closePosition.
        // Solidity allows tuple assignment from struct return. We'll read the openPosition fields by calling c.pre(account) then position helpers.
        // To work with minimal features, call c.pre(account) and then call c.pre() (global pre) to get contract-level pre too for comparison as proxy.

        // Read entire PrePosition for account by calling c.pre(account) into local variables
        (uint256 acc_oracleVersion, (UFixed18 acc_open_maker, UFixed18 acc_open_taker), (UFixed18 acc_close_maker, UFixed18 acc_close_taker)) = c.pre(account);

        bool reverted;
        if (isMake) {
            try c.openMakeFor(account, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.openTakeFor(account, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Read pre after
        (uint256 acc_oracleVersion2, (UFixed18 acc_open_maker2, UFixed18 acc_open_taker2), (UFixed18 acc_close_maker2, UFixed18 acc_close_taker2)) = c.pre(account);

        // Build assertions:
        // If the call reverted, pre must be unchanged. If it succeeded, the respective open side increased by exactly amount while the other side is unchanged.
        if (reverted) {
            assert(
                acc_oracleVersion2 == acc_oracleVersion &&
                acc_open_maker2.eq(acc_open_maker) &&
                acc_open_taker2.eq(acc_open_taker) &&
                acc_close_maker2.eq(acc_close_maker) &&
                acc_close_taker2.eq(acc_close_taker)
            );
        } else {
            if (isMake) {
                assert(
                    acc_open_maker2.eq(acc_open_maker.add(amount)) &&
                    acc_open_taker2.eq(acc_open_taker) &&
                    acc_close_maker2.eq(acc_close_maker) &&
                    acc_close_taker2.eq(acc_close_taker)
                );
            } else {
                assert(
                    acc_open_taker2.eq(acc_open_taker.add(amount)) &&
                    acc_open_maker2.eq(acc_open_maker) &&
                    acc_close_maker2.eq(acc_close_maker) &&
                    acc_close_taker2.eq(acc_close_taker)
                );
            }
        }
    }

