            }
        }

        // Read pre-position after
        (uint256 afterOracleVersion,
         UFixed18 after_open_maker, UFixed18 after_open_taker,
         UFixed18 after_close_maker, UFixed18 after_close_taker) = _readPre(account);

        // General rule:
        // If the call reverted -> pre() is entirely unchanged.
        // If the call succeeded -> only the corresponding open side increased by exactly `amount`,
        // other components equal and oracleVersion unchanged.
        if (reverted) {
            assert(
                afterOracleVersion == beforeOracleVersion &&
                after_open_maker.eq(before_open_maker) &&
                after_open_taker.eq(before_open_taker) &&
                after_close_maker.eq(before_close_maker) &&
                after_close_taker.eq(before_close_taker)
            );
