                assert(
                    afterOracleVersion == beforeOracleVersion &&
                    after_open_maker.eq(before_open_maker.add(amount)) &&
                    after_open_taker.eq(before_open_taker) &&
                    after_close_maker.eq(before_close_maker) &&
                    after_close_taker.eq(before_close_taker)
                );
            } else {
                assert(
                    afterOracleVersion == beforeOracleVersion &&
                    after_open_taker.eq(before_open_taker.add(amount)) &&
                    after_open_maker.eq(before_open_maker) &&
                    after_close_maker.eq(before_close_maker) &&
                    after_close_taker.eq(before_close_taker)
                );
            }
        }
    }

    // Helper to read c.pre(account) into flat tuple because Solidity cannot destructure nested structs directly in return
    function _readPre(address account) private view returns (
        uint256 oracleVersion,
        UFixed18 open_maker, UFixed18 open_taker,
        UFixed18 close_maker, UFixed18 close_taker
    ) {
        // c.pre(account) returns (PrePosition memory) with fields (oracleVersion, openPosition, closePosition)
        // Solidity allows assigning returned struct to a tuple of its components by matching layout.
        (oracleVersion, (open_maker, open_taker), (close_maker, close_taker)) = c.pre(account);
    }

    receive() external payable {}
}

