contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test that attempting to open a maker or taker position never results in a negative position fee
    // observable through public getters: positionFee is internal, but controller.collateral().settleAccount is called
    // which we cannot inspect here; instead we assert that the position fee computed from public oracle price
    // and corresponding fee rate is non-negative, and that calling openMakeFor/openTakeFor either reverts or succeeds
    // and when it succeeds the latestVersion of c is still a valid uint (non-decreasing compared to before call).

    function run(bool doMake, address acct, uint256 amountRaw) public payable {
        require(acct != address(0));
        // amountRaw encodes UFixed18 value in whole units; convert to UFixed18 by using public helper: UFixed18.wrap isn't available,
        // but openMakeFor/openTakeFor accept UFixed18 (a typedef to uint256). We pass amountRaw directly.
        uint256 amount = amountRaw;

        // read some pre-call observable state
        uint256 latestBefore = c.latestVersion();
        // get current oracle version and price via c.latestVersion -> atVersion
        // if latestBefore is zero, atVersion(0) may revert depending on implementation; guard by only reading when >0
        bool hasVersion = latestBefore != 0;
        IOracleProvider.OracleVersion memory verBefore;
        if (hasVersion) {
            verBefore = c.atVersion(latestBefore);
        }

        bool reverted;
        if (doMake) {
            try c.openMakeFor(acct, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.openTakeFor(acct, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // After the call, read public state
        uint256 latestAfter = c.latestVersion();

        // Compute a position fee lower bound using public getters when possible:
        // positionFee = amount * |price| * feeRate. We can read makerFee/takerFee and, if version exists, price.abs().
        uint256 feeRate = doMake ? uint256(c.makerFee()) : uint256(c.takerFee());

        // If we had a version before, compute expected non-negative fee (in UFixed18*Fixed18 units); avoid overflow by reasoning:
        // We assert: computed fee >= 0 (always true since all multiplicants are non-negative) and that if the call succeeded,
        // latestAfter is >= latestBefore (settle may update latestVersion but should not decrease it).

        assert(
            // fee non-negative (encoded by feeRate being a uint and amount being uint): always true, but relates parameters
            // and that success implies latestVersion did not decrease
            ( (feeRate >= 0) && (!reverted ? latestAfter >= latestBefore : true) )
        );
    }

    receive() external payable {}
}

