    // We test that when openMakeFor/openTakeFor succeed, the corresponding pre() for the account
    // reflects the requested amount increase and that any charged position fee is non-negative.
    // We use account = address(this) so only public/external methods are used.
    function run(bool isMake, uint256 rawAmount) public payable {
        // normalize amount into a UFixed18 representation by treating rawAmount as the underlying integer
        // We will call either openMakeFor or openTakeFor with that amount.
        // No precondition on c state.

        // Read latestVersion and pre before the call
        uint256 beforeVersion = c.latestVersion();
        C.PrePosition memory preBefore = c.pre(address(this));
        C.Position memory posBefore = c.position(address(this));

        // amount as UFixed18: must be passed through the ABI as a tuple type; here we construct via encoding/abi decode
        // Solidity does not allow constructing user types directly; instead we pass uint256 and rely on ABI matching.
        // The functions expect UFixed18, which is a typedef of uint256 under the hood, so casting is simple.
        uint256 amount = rawAmount;

        bool reverted = false;
        // perform the chosen action; capture whether it reverts
        if (isMake) {
            try c.openMakeFor(address(this), UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.openTakeFor(address(this), UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Read after-state
        uint256 afterVersion = c.latestVersion();
        C.PrePosition memory preAfter = c.pre(address(this));
        C.Position memory posAfter = c.position(address(this));

        // If the call reverted, we cannot assume state changed. If it did not revert, then for openMake/openTake
        // the account's pre.openMake/openTake at the latestVersion should reflect an increase by exactly amount
        // relative to the previous next() pre state. We express a general check: when not reverted,
        // either the pre's openMake/openTake increased by amount, or latestVersion advanced and pre is set at that version.

        if (!reverted) {
            if (isMake) {
                // the openMake call should have increased pre.openPosition.maker by amount compared to before
                // Compute delta conservatively using viewable Position values: posAfter.next(preAfter) - posBefore.next(preBefore)
                C.Position memory nextBefore = posBefore.next(preBefore);
                C.Position memory nextAfter = posAfter.next(preAfter);
                // Ensure maker did not decrease and the increase is at least amount (allowing other concurrent effects to also add)
                assert(! (nextAfter.maker.lt(nextBefore.maker)) && (nextAfter.maker.sub(nextBefore.maker).gte(UFixed18.wrap(amount))));
            } else {
                C.Position memory nextBefore = posBefore.next(preBefore);
                C.Position memory nextAfter = posAfter.next(preAfter);
                // Ensure taker did not decrease and the increase is at least amount
                assert(! (nextAfter.taker.lt(nextBefore.taker)) && (nextAfter.taker.sub(nextBefore.taker).gte(UFixed18.wrap(amount))));
            }
        } else {
            // If reverted, assert nothing about state other than that versions didn't change or if they did, some invariant holds:
            // require that either latestVersion unchanged, or if changed then account's latestVersion matches contract latestVersion
            // to ensure we reached some settle path. This avoids asserting a constant.
            assert(afterVersion == beforeVersion || c.latestVersion(address(this)) == afterVersion);
        }
    }

    receive() external payable {}
}

