    // resulting next() position's maker (for make) or taker (for take) is >= previous and
    // increased by at least the requested amount.
    // We use address(this) as the account.
    function run(bool isMake, uint256 rawAmount) public payable {
        require(true);

        // Read before-state: current stored position and pre for this account
        C.Position memory posBefore = c.position(address(this));
        C.PrePosition memory preBefore = c.pre(address(this));

        // Compute next before = posBefore.next(preBefore) by calling public helpers: we only have public view position and pre.
        // The contract C exposes position(...) and pre(...). We cannot call .next() externally because it's a library function on Position type not part of C's public API.
        // However positionAtVersion(latestVersion()) returns the Position at latest version; we can use position(address) and pre(address) together
        // to observe the account state before and after and then compare their next() via comparing pos+pre.open/close deltas through the public getters.
        // To simplify given constraints, we'll rely on observable behavior: after a successful openMakeFor/openTakeFor,
        // either the account's position().maker/taker (public) increases by at least amount, or the account's pre().openPosition contains the amount.

        // Call chosen action and capture whether it reverts
        bool reverted;
        reverted = false;
        uint256 amount = rawAmount;
        if (isMake) {
            try c.openMakeFor(address(this), amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.openTakeFor(address(this), amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Read after-state
        C.Position memory posAfter = c.position(address(this));
        C.PrePosition memory preAfter = c.pre(address(this));

        // Assert the general rule
        // If the call succeeded (not reverted) then either:
        //  - the on-chain settled position's corresponding side (maker/taker) is >= before and increased by at least amount,
        //    OR
        //  - the account's pre().openPosition for that side is >= amount (i.e., the pending open includes the requested amount).
        // This is observable via public getters position(...) and pre(...).
        if (!reverted) {
            if (isMake) {
                // posAfter.maker >= posBefore.maker AND increase >= amount, OR preAfter.openPosition.maker >= amount
                bool makerNonDecreasing = (posAfter.maker >= posBefore.maker);
                bool makerIncreaseAtLeast = (posAfter.maker - posBefore.maker >= amount);
                bool pendingIncludes = (preAfter.openPosition.maker >= amount);
                assert((makerNonDecreasing && makerIncreaseAtLeast) || pendingIncludes);
            } else {
                bool takerNonDecreasing = (posAfter.taker >= posBefore.taker);
                bool takerIncreaseAtLeast = (posAfter.taker - posBefore.taker >= amount);
                bool pendingIncludes = (preAfter.openPosition.taker >= amount);
                assert((takerNonDecreasing && takerIncreaseAtLeast) || pendingIncludes);
            }
        } else {
            // If reverted, assert nothing about positions changing; still require that revert flag is a boolean (trivial),
            // but we must end with exactly one assert, so assert reverted implies that after-state equals before-state for settled positions
            // (a weak observable guarantee): posAfter equals posBefore.
            assert(reverted ? (posAfter.maker == posBefore.maker && posAfter.taker == posBefore.taker) : true);
        }
    }

    receive() external payable {}
}

