        (uint256 afterOracleVersion, uint256 afterOpenMaker, uint256 afterOpenTaker, uint256 afterCloseMaker, uint256 afterCloseTaker) = c.pre(account);

        // If the call did not revert, the openPosition.maker must have increased by at least amount
        assert(reverted || afterOpenMaker >= beforeOpenMaker + amount);
    }

    receive() external payable {}
}

