contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public function: tries either openMakeFor or openTakeFor and asserts the invariant
    // We cannot construct UFixed18 directly from uint, so we pass through a UFixed18 value by
    // calling the contract with a caller-provided UFixed18 via ABI encoding using bytes.
    // However, Solidity requires correctly typed arguments when calling external functions.
    // To avoid type conversion, we call the overloads by preparing calldata and using low-level call.

    function run(address account, uint256 rawAmount, bool doMake) public payable {
        require(account != address(0));

        // Observe before state
        uint256 latestBefore = c.latestVersion();
        bool closedBefore = c.closed();

        // Build calldata for openMakeFor(address, UFixed18) or openTakeFor(address, UFixed18)
        // Function selectors from the interface (computed off-chain normally). We'll compute them here using Solidity's abi.encodeWithSelector.
        // Obtain selector by using the function signature string.
        bytes memory callData;
        if (doMake) {
            // signature: openMakeFor(address,(uint256)) wouldn't match; UFixed18 is a user-defined type alias to uint256,
            // so its ABI type is uint256. The ABI signature is "openMakeFor(address,uint256)".
            callData = abi.encodeWithSelector(bytes4(keccak256("openMakeFor(address,uint256)")), account, rawAmount);
        } else {
            callData = abi.encodeWithSelector(bytes4(keccak256("openTakeFor(address,uint256)")), account, rawAmount);
        }

        // Perform the low-level call; capture whether it reverted
        (bool ok,) = address(c).call(callData);
        bool reverted = !ok;

        // Observe after state
        uint256 latestAfter = c.latestVersion();
        bool closedAfter = c.closed();

        // General rule: latestVersion must not decrease and closed flag must remain unchanged
        assert(latestAfter >= latestBefore && closedAfter == closedBefore && reverted == reverted);
        // Note: the tautological 'reverted == reverted' is present only to ensure the assert uses the local variable
        // while not changing the intended rule. The real enforced conditions are latestAfter >= latestBefore and closedAfter == closedBefore.
    }

    receive() external payable {}
}

