contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take an account address (account), and an amount to open/close (amount).
    // The test attempts to open a maker position for account and then close it for the same account.
    // It asserts that both operations do not revert, and that after both calls the account's latestVersion
    // equals the product latestVersion (account is settled to current product version).
    function run(address account, UFixed18 amount) public payable {
        require(account != address(0));

        // Record product latestVersion before operations
        uint256 productLatestBefore = c.latestVersion();

        bool openReverted;
        try c.openMakeFor(account, amount) {
            openReverted = false;
        } catch {
            openReverted = true;
        }

        bool closeReverted;
        try c.closeMakeFor(account, amount) {
            closeReverted = false;
        } catch {
            closeReverted = true;
        }

        // Read observable latest versions
        uint256 productLatestAfter = c.latestVersion();
        uint256 accountLatest = c.latestVersion(account);

        // General rule: if both calls succeeded (did not revert), then the account's latestVersion
        // must equal the product latestVersion (the account was settled to latest product version).
        assert(!( !openReverted && !closeReverted ) || accountLatest == productLatestAfter);
    }

    receive() external payable {}
}
